import{_ as t,o,c as a,a3 as d}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"捕获后端","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"捕获后端 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/design/capture-backends"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/design/capture-backends"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/capture-backends"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/capture-backends"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/capture-backends"}]]},"headers":[],"relativePath":"zh/catter/design/capture-backends.md","filePath":"zh/catter/design/capture-backends.md","lastUpdated":1793091486000}'),r={name:"zh/catter/design/capture-backends.md"};function c(i,e,n,l,s,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="捕获后端" tabindex="-1">捕获后端 <a class="header-anchor" href="#捕获后端" aria-label="Permalink to &quot;捕获后端&quot;">​</a></h1><p>捕获后端（capture backend）是 catter 获取构建命令的方式：它启动构建，将构建启动的每条命令上报给 catter；catter 让会话的各个 handler 决定如何处理命令，并向它们报告命令的结束情况。无论由哪个后端上报，handler 看到的命令、决定和事件都一样。</p><h2 id="选择后端" tabindex="-1">选择后端 <a class="header-anchor" href="#选择后端" aria-label="Permalink to &quot;选择后端&quot;">​</a></h2><p><code>--capture &lt;backend&gt;</code> 指定捕获构建的后端，默认是 <code>hook</code>，也是目前唯一的后端。<code>--from &lt;file&gt;</code> 回放一次录制的构建，而不运行构建：回放录制的构建不涉及捕获，因此使用 <code>--from</code> 时不能同时使用 <code>--capture</code>；指定不存在的后端名称也会报错。这两种错误都会在任何程序运行之前报告。</p><p>handler 从会话的 <code>initialize</code> 消息得知后端：其中的 <code>mode</code> 是后端的名字，回放录制的构建时则为 <code>replay</code>。</p><h2 id="后端做什么" tabindex="-1">后端做什么 <a class="header-anchor" href="#后端做什么" aria-label="Permalink to &quot;后端做什么&quot;">​</a></h2><ul><li><strong>启动构建</strong>，构建怎样结束，catter 就怎样结束。catter 代替构建命令运行：发给 catter 的 SIGTERM、SIGINT 或 SIGHUP 会转给构建命令，catter 被杀死时构建命令也随之结束。</li><li><strong>在每条命令运行前上报命令信息</strong>：工作目录、程序、参数和环境变量，以及启动它的命令。并行构建的命令会同时上报。catter 未能捕获的命令则以 <code>error</code> 的形式上报。</li><li><strong>按 handler 的决定运行每条命令</strong>：原样运行（<code>skip</code>）、修改后运行（<code>modify</code>、<code>edit</code>），或者不运行（<code>drop</code>，命令以退出码 0 结束）。一旦某个 handler 中止构建或出错，这条命令以及构建在它之后启动的每条命令都不运行，直接以退出码 1 结束。</li><li><strong>上报每条命令的结束情况</strong>，先于构建在这条命令结束之后启动的任何命令，也先于构建本身的结束。</li></ul><h2 id="后端一览" tabindex="-1">后端一览 <a class="header-anchor" href="#后端一览" aria-label="Permalink to &quot;后端一览&quot;">​</a></h2><h3 id="hook-默认" tabindex="-1">hook（默认） <a class="header-anchor" href="#hook-默认" aria-label="Permalink to &quot;hook（默认）&quot;">​</a></h3><ul><li><strong>原理</strong>：将钩子库加载到构建的每个进程中，拦截进程创建（Linux 和 macOS 上的 <code>execve</code> / <code>posix_spawn</code> 族，Windows 上的 <code>CreateProcess</code>）。在 Linux 和 macOS 上，每条命令随后通过 <code>catter-proxy</code> 运行：它向 catter 询问如何处理命令，按决定运行命令，并为它加载钩子；在 Windows 上，钩子自己询问 catter，并按 catter 的决定启动程序。参见<a href="./hook-mechanism">钩子机制</a>和 <a href="./ipc-protocol">IPC 协议</a>。</li><li><strong>平台</strong>：Linux、macOS、Windows。</li><li><strong>捕获范围</strong>：构建的每个进程及启动该进程的命令，但无法加载钩子的程序所启动的进程除外：这样的程序本身仍会上报，并按决定运行，只是不带钩子。在 macOS 上，这类程序是 Apple 自带的工具（<code>/bin/sh</code>、<code>/usr/bin/make</code>），以及在 Rosetta 下运行的 Intel 程序；Apple 自带的工具以 arm64e 运行，系统完整性保护（System Integrity Protection）会移除其中的钩子。在 Windows 上，这类程序是 32 位（x86）程序。Windows 程序以其他账户启动的程序则完全看不到。</li><li>构建及其命令直接使用 catter 自己的标准输入、标准输出和标准错误：它们直接写到终端，颜色不丢，输出顺序也和写入时一致。</li></ul><h3 id="replay-from" tabindex="-1">replay（<code>--from</code>） <a class="header-anchor" href="#replay-from" aria-label="Permalink to &quot;replay（`--from`）&quot;">​</a></h3><ul><li><strong>原理</strong>：回放文件中录制的构建，而不运行构建：按文件中的顺序重现每条命令、错误和退出事件，并使用文件记录的 ID 和父命令。构建以文件记录的退出码结束。</li><li><strong>动作</strong>：没有任何命令运行，因此 <code>skip</code>、<code>drop</code>、<code>modify</code> 和 <code>edit</code> 不改变任何东西。<code>abort</code> 像结束真实构建一样结束回放：之后的事件不再送达 handler，catter 以 1 退出。</li></ul><h3 id="wrapper-计划中" tabindex="-1">wrapper（计划中） <a class="header-anchor" href="#wrapper-计划中" aria-label="Permalink to &quot;wrapper（计划中）&quot;">​</a></h3><ul><li><strong>原理</strong>：编译器 shim（包装程序）放在构建的 <code>PATH</code> 最前面，并由 <code>CC</code>、<code>CXX</code> 等变量指定，代替编译器运行：每个 shim 上报自己的命令，并按决定运行真正的编译器。</li><li><strong>适用场景</strong>：钩子无法捕获的构建，例如 macOS 上由 Apple 自带的工具运行的构建。</li><li><strong>预期限制</strong>：只能捕获它包装的程序，构建通过自行指定的路径运行的编译器会绕过捕获；命令的父命令是启动它的、离它最近的被包装程序，或者构建命令。</li><li><strong>状态</strong>：尚未实现。</li></ul><h2 id="能力矩阵" tabindex="-1">能力矩阵 <a class="header-anchor" href="#能力矩阵" aria-label="Permalink to &quot;能力矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后端</th><th>平台</th><th>捕获方式</th><th>动作</th><th>父命令</th><th>状态</th></tr></thead><tbody><tr><td>hook</td><td>Linux / macOS / Windows</td><td>构建的每个进程中的钩子</td><td><code>skip</code> <code>drop</code> <code>abort</code> <code>modify</code> <code>edit</code></td><td>启动它的进程</td><td>已实现（默认）</td></tr><tr><td>replay</td><td>任意</td><td>录制的构建（<code>--from</code>）</td><td>仅 <code>abort</code> 生效</td><td>按录制内容</td><td><span class="status-badge ok">已实现</span></td></tr><tr><td>wrapper</td><td>跨平台</td><td><code>PATH</code> 上的编译器 shim，<code>CC</code> / <code>CXX</code></td><td>预期全部支持</td><td>离它最近的被包装程序</td><td><span class="status-badge note">计划中</span></td></tr></tbody></table><h2 id="为任意后端编写-handler" tabindex="-1">为任意后端编写 handler <a class="header-anchor" href="#为任意后端编写-handler" aria-label="Permalink to &quot;为任意后端编写 handler&quot;">​</a></h2><ul><li>不要假定使用某个特定后端：<code>initialize</code> 会指明所用后端（<code>mode</code>）。</li><li>命令的父命令是后端所能看到的、启动它的命令：依赖进程树的功能（命令树、目标树）不应假设两者之间的每个进程都会出现。</li></ul>',18)])])}const u=t(r,[["render",c]]);export{g as __pageData,u as default};
